import copy
import json
import tomllib
from datetime import date, datetime, time
from pathlib import Path

UNSET = "__unset__"
BASE = Path("/config/base.toml")
ENVDIR = Path("/config/env")
OUTDIR = Path("/out")


def merge(base, override):
    """Merge override onto base (both already plain Python objects)."""
    if isinstance(base, dict) and isinstance(override, dict):
        result = copy.deepcopy(base)
        for k, v in override.items():
            if v == UNSET and isinstance(v, str):
                result.pop(k, None)
            elif k in result:
                result[k] = merge(result[k], v)
            else:
                result[k] = copy.deepcopy(v)
        return result
    if isinstance(override, str) and override == UNSET:
        return None  # key absence handled by caller only for dict members
    return copy.deepcopy(override)


def to_jsonable(obj):
    if isinstance(obj, dict):
        return {k: to_jsonable(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [to_jsonable(v) for v in obj]
    if isinstance(obj, (datetime, date, time)):
        return obj.isoformat()
    return obj


def main():
    with BASE.open("rb") as f:
        base = tomllib.load(f)

    names = sorted(p.stem for p in ENVDIR.glob("*.toml"))
    for name in names:
        with (ENVDIR / f"{name}.toml").open("rb") as f:
            override = tomllib.load(f)
        merged = to_jsonable(merge(base, override))
        text = json.dumps(merged, indent=2, sort_keys=True, ensure_ascii=False)
        (OUTDIR / f"{name}.json").write_text(text + "\n", encoding="utf-8")

    (OUTDIR / "index.txt").write_text("".join(n + "\n" for n in names), encoding="utf-8")
    print("wrote:", ", ".join(names) or "(none)")


if __name__ == "__main__":
    main()
